mapper.select:
select id, project_id, user_account_id, leader_account_id, status, disabled_at, created_at
from chat_sessions
where id = #{id}

select count(*)
from chat_sessions cs
inner join projects p on p.id = cs.project_id
left join project_members pm
       on pm.project_id = cs.project_id
      and pm.account_id = #{accountId}
      and pm.join_status = 'JOINED'
where cs.id = #{sessionId}
  and (p.owner_account_id = #{accountId}
    or p.leader_account_id = #{accountId}
    or pm.id is not null)
